// Why Code: validare de schemă + textul notificării în română (HTML Telegram); nicio combinație de noduri native nu le acoperă curat.
// Aplicația trimite deja concluzia din dashboard (`conclusion`) și checklistul (`missing`), calculate și testate acolo; aici doar le așezăm.
const body = $('Webhook claim.completed').first().json.body ?? {};
const fail = (m) => { throw new Error(`Payload claim.completed invalid: ${m}`); };

if (body.event !== 'claim.completed') fail('event');
if (!/^[0-9a-f-]{36}$/i.test(body.claimId ?? '')) fail('claimId');
if (typeof body.ref !== 'string' || !/^[A-Z0-9-]{3,40}$/.test(body.ref)) fail('ref');
if (!/^https:\/\//.test(body.pdfUrl ?? '')) fail('pdfUrl (trebuie https)');
if (!body.parties?.A || !body.parties?.B) fail('parties');
const missing = Array.isArray(body.missing) ? body.missing : [];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const join = (parts, sep = ', ') => parts.filter(Boolean).join(sep);

// Detaliile unui șofer, pe 4 rânduri. Circumstanțele apar ca numere (ca pe formularul amiabilei), ca mesajul să rămână scurt.
const partyBlock = (p, role) => {
  const car = join([p.plate, p.vehicle]) || 'vehicul necunoscut';
  const client = p.client
    ? (p.client === p.driver ? 'client al agenției' : `client al agenției: ${p.client}`)
    : 'nu e în portofoliu';
  const lines = [
    `<b>${role}</b>  ${esc(car)}`,
    `${esc(join([p.driver || 'șofer necunoscut', p.contact]))} (${esc(client)})`,
    esc(join([p.insurer || 'asigurător necunoscut', p.policyNo && `polița ${p.policyNo}`, p.impact && `lovit ${String(p.impact).toLocaleLowerCase('ro-RO')}`])),
  ];
  const list = p.circumstances ?? [];
  lines.push(`<i>Circumstanțe: ${list.length ? esc(list.map((x) => x.n).join(', ')) : 'nebifate'}</i>`);
  return lines.join('\n');
};

const c = body.conclusion;
const verdict = c
  ? [...(c.status ?? []).map((s) => (c.complete ? `✅ ${esc(s)}` : esc(s))), ...(c.warnings ?? []).map((w) => `⚠️ ${esc(w)}`), ...(c.extras ? [esc(c.extras)] : [])]
  : missing.length === 0 ? ['✅ Dosar complet.'] : missing.map((m) => `${m.blocking ? '•' : '◦'} ${esc(m.label)}`);

const url = String(body.brokerUrl ?? '');
// Telegram refuză linkuri spre localhost; atunci linkul lipsește, dosarul e oricum în dashboard.
const link = /^https:\/\//.test(url) && !/\/\/(localhost|127\.0\.0\.1)/.test(url) ? `<a href="${esc(url)}">Deschide dosarul în BrokerPilot</a>` : '';

const text = join([
  `<b>Amiabilă nouă ${esc(body.ref)}</b>\n${esc(join([body.occurredAt, body.place]))}`,
  partyBlock(body.parties.A, 'A'),
  partyBlock(body.parties.B, 'B'),
  verdict.join('\n'),
  join([`Poze: A ${body.photoCounts?.A ?? 0}, B ${body.photoCounts?.B ?? 0}. Schiță: ${body.hasSketch ? 'da' : 'nu'}.`, link], '\n'),
], '\n\n');

// Legenda unui document Telegram are maximum 1024 de caractere.
const caption = text.length <= 1024 ? text : text.slice(0, 1020) + '…';

// Rezumat determinist salvat pe dosar (fără LLM: datele personale nu pleacă spre un model cloud). Un rezumat AI vine după WF00.
const party = (p, role) => {
  const car = join([p.plate, p.vehicle], ' ') || 'vehicul necunoscut';
  const impact = p.impact ? `, lovit: ${p.impact}` : '';
  const circ = p.circumstances?.length ? ` Circumstanțe: ${p.circumstances.map((x) => x.n).join(', ')}.` : '';
  return `${role}: ${p.driver || 'șofer necunoscut'}, ${car} (${p.insurer || 'asigurător necunoscut'})${impact}.${circ}`;
};
const summary = [
  `Amiabilă ${body.ref}, ${body.occurredAt}, ${body.place}.`,
  party(body.parties.A, 'A'),
  party(body.parties.B, 'B'),
  `Poze: A ${body.photoCounts?.A ?? 0}, B ${body.photoCounts?.B ?? 0}. Schiță: ${body.hasSketch ? 'da' : 'nu'}.`,
].join('\n');

const chats = String($env.TG_BROKER_CHAT_IDS ?? '').split(',').map((s) => s.trim()).filter(Boolean);
if (chats.length === 0) fail('TG_BROKER_CHAT_IDS lipsește');

return chats.map((chatId) => ({
  json: { chatId, claimId: body.claimId, ref: body.ref, pdfUrl: body.pdfUrl, fileName: `${body.ref}.pdf`, caption, summary, missing },
}));
